T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "Ajoute une collecte automatique en plus du réglage Fouille automatique de Blizzard, qui reste inchangé. Les emplacements verrouillés et les confirmations restent manuels.")
T("Adds every spell of this group that you know. Spells on another bar move here.", "Ajoute tous les sorts connus de ce groupe. Ceux d’une autre barre sont déplacés ici.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "Ajoute à l'infobulle principale de Blizzard le rang de guilde, la cible de l'unité, les niveaux d'objet, la monture actuelle de l'unité et des détails d'objets ou de sorts, et peut afficher les noms des joueurs sans titre. Votre propre niveau d'objet et celui de l'unité ouverte dans la fenêtre d'inspection ne demandent aucune requête. Les niveaux d'objet des autres joueurs survolés sont une option à part qui envoie des demandes d'inspection : au plus une par survol, jamais pendant que la fenêtre d'inspection ou une autre inspection est occupée. Les montures sont lues une fois à l'ouverture d'une infobulle d'unité, hors combat ; un changement apparaît au survol suivant. Placez le coin fixe dans le mode d'édition de MSUF ; les décalages du curseur s'appliquent à l'ancrage au curseur.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "Ajoute le score Mythique+ de la saison en cours à l'infobulle principale d'un autre joueur lorsque Blizzard fournit un score public. Les scores inconnus ou restreints restent masqués.")
