T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "Après un parcours Mythique+ terminé ou un combat de raid réussi, affiche les résultats publics dans une carte séparée. Choisissez les chiffres affichés et la durée d'ouverture. Le dernier résultat peut être rouvert ici. Le combat retarde l'affichage jusqu'à ce qu'il soit possible en toute sécurité.")
