T("Apply a graphics preset once. Balanced changes your general settings and keeps your separate raid settings.\nRaid / Dungeon changes only the separate instance settings and enables them.\nTextures, particle density and outlines stay as you set them; projected textures stay on. Unsupported settings are skipped.\nSharpening, contrast and audio reverb are optional and apply globally.\nYour originals are saved outside profiles. Restore keeps later manual changes. FPS gains depend on your hardware and the scene.", "Appliquez un préréglage graphique une seule fois. Équilibré modifie les réglages généraux et conserve vos réglages de raid distincts.\nRaid / Donjon modifie uniquement les réglages d’instance distincts et les active.\nTextures, densité des particules et contours restent tels que vous les avez réglés ; les textures projetées restent activées. Les réglages incompatibles sont ignorés.\nLa netteté, le contraste et la réverbération audio sont facultatifs et s’appliquent globalement.\nVos valeurs d’origine sont sauvegardées hors des profils. La restauration conserve les modifications manuelles ultérieures. Le gain de FPS dépend du matériel et de la scène.")
