T("Blizzard keeps 128 lines in each window. A higher limit lets you scroll back further and lets saved history fill the window.", "Blizzard conserve 128 lignes par fenêtre. Une limite plus élevée permet de remonter plus loin et de remplir la fenêtre avec l'historique enregistré.")
T("Blizzard keeps every original font size and style flag.", "Blizzard conserve chaque taille de police et attribut de style d'origine.")
T("Blizzard keeps its text sizes and outlines.", "Blizzard conserve ses tailles de texte et ses contours.")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "Blizzard conserve les graphismes des boutons, les clics, les infobulles, les états d'activation et les notifications. Des glyphes optionnels sont disponibles dans les réglages détaillés. Les changements visuels ne s'appliquent que hors combat.")
T("Blizzard layout captured", "Disposition Blizzard capturée")
T("Blizzard layout imported", "Disposition Blizzard importée")
T("Blizzard original", "Blizzard d'origine")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "Blizzard gère les clignotements d'aggro, les surbrillances progressives et les icônes de ciblage souple. Les couleurs optionnelles teintent les textures de menace existantes ; la couleur de menace de la barre de vie reste sous la couleur de rôle. Les icônes de ciblage souple nécessitent aussi l'activation des icônes de plaques et une cible souple correspondante en jeu.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "Blizzard gère les icônes d'aura et leurs mises à jour. Choisissez Garder le réglage Blizzard ou Personnaliser pour chaque type d'unité. Les buffs, débuffs et effets de contrôle se sélectionnent et se déplacent séparément dans l'aperçu. La taille des auras utilise le réglage propre à Blizzard.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "Blizzard gère ces éléments. Le réglage de l'icône de rareté s'applique à toutes les barres d'info ; les icônes de cible de raid ne sont masquées que sur les barres ennemies. Les détails de la barre d'incantation contrôlent celle de Blizzard. L'aperçu et les barres en jeu utilisent les mêmes options.")
T("Blizzard personal auras", "Auras personnelles Blizzard")
T("Blizzard plate size (health bar + elements)", "Taille des barres Blizzard (vie + éléments)")
T("Blizzard plate style", "Style des barres Blizzard")
T("Blizzard plates", "Barres d'info Blizzard")
T("Blizzard player auras", "Auras du joueur de Blizzard")
T("Blizzard portrait", "Portrait Blizzard")
T("Blizzard raid target icon on enemy plates", "Icône de cible de raid Blizzard sur les barres ennemies")
T("Blizzard setting", "Réglage Blizzard")
T("Blizzard shield", "Bouclier Blizzard")
T("Blizzard spell icon", "Icône de sort Blizzard")
T("Blizzard supplies health and aura updates. List edits and preview work during combat; color pickers work after combat.", "Blizzard fournit les mises à jour de vie et d'auras. La liste et l'aperçu fonctionnent en combat ; les sélecteurs de couleur après.")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "Blizzard fournit la texture, les couleurs, la progression et les interruptions de la barre d'incantation. Personnalisez ici son texte et ses détails. Sélectionnez et déplacez chaque élément d'incantation dans l'aperçu ; les positions s'appliquent hors combat.")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "Blizzard fournit les icônes. La Suite conserve ses propres plaques de bouton, le cadre de la barre et l'espacement. Les clics, infobulles et notifications d'origine restent intacts.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "Blizzard fournit le nom et les valeurs de vie. Mapko demande des plaques ennemies complètes et les deux valeurs de vie afin que les ennemis normaux affichent aussi du texte. Largeur et hauteur ne modifient que la barre de vie ennemie en pixels ; 0 conserve les dimensions choisies. Fond, bordure et remplissage de rôle sont des couches distinctes dans l'aperçu ; faites un clic droit sur une couche pour son réglage. Les couleurs de rôle utilisent la palette enregistrée ; le mana n'est qu'un indice de lanceur de sorts. Ouvrez le menu à trois points ici ou Plaques de nom dans Couleurs MSUF pour modifier la palette.")
T("Blizzard symbols", "Symboles Blizzard")
T("Blizzard talent mapping: %d", "Lien de talent Blizzard : %d")
T("Blizzard window controls", "Contrôles des fenêtres Blizzard")
T("Blizzard windows", "Fenêtres Blizzard")
T("Blizzard yellow and chat system text", "Jaune Blizzard et texte système de la discussion")
T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "Le gestionnaire de temps de recharge de Blizzard s'arrête complètement. Tant que vos cadres MSUF suivent ses barres, MSUF le maintient actif de façon invisible.")
T("Blizzard's aggro, target, focus and soft target signals.", "Signaux Blizzard de menace, de cible, de focalisation et de cible douce.")
T("Blizzard's bars keep running, invisible, so frames that other addons attach to them stay in place.", "Les barres de Blizzard restent actives, invisibles, pour que les cadres que d'autres addons y attachent restent en place.")
T("Blizzard's combined switch for pets, guardians and totems. The separate choices set each kind on its own.", "Le réglage commun de Blizzard pour les familiers, gardiens et totems. Les options séparées règlent chaque type individuellement.")
T("Blizzard's cooldown bars", "Barres de recharges Blizzard")
T("Blizzard's cooldown bars are off.", "Les barres de recharges de Blizzard sont désactivées.")
T("Blizzard's cooldown bars keep running invisibly.", "Les barres de recharges de Blizzard restent actives de façon invisible.")
