T("Blizzard's distance and stacking options. Keep Blizzard setting changes nothing; other choices return to Blizzard's value when the skin turns off.", "Options de distance et d'empilement de Blizzard. Conserver le réglage de Blizzard ne change rien ; les autres choix rétablissent sa valeur à la désactivation de l'habillage.")
T("Blizzard's entry for this spell is already on this bar.", "L'entrée Blizzard de ce sort est déjà sur cette barre.")
T("Blizzard's list has too many entries for one bar.", "La liste de Blizzard contient trop d'entrées pour une seule barre.")
T("Blizzard's original Micro Bar and buttons. Use Blizzard Edit Mode to move it.", "La micro-barre et les boutons d'origine de Blizzard. Utilisez le mode Édition de Blizzard pour la déplacer.")
T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "Les boutons propres à Blizzard restent fonctionnels. La rangée est leur position de départ ; faites glisser librement chaque icône dans l'aperçu.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "L'animation de recharge de Blizzard remplit l'anneau : le temps de recharge global après chaque technique, et les incantations ou canalisations pendant qu'elles durent. Une incantation remplace le temps de recharge global jusqu'à sa fin ; le bord lumineux montre où elle en est.")
T("Blizzard's own icons and castbar details.", "Icônes et détails de barre d'incantation propres à Blizzard.")
T("Blizzard's own nameplate options. Keep Blizzard setting changes nothing; other choices go back to Blizzard's value when the skin turns off.", "Options de barres d'info propres à Blizzard. Garder le réglage Blizzard ne change rien ; les autres choix reviennent à la valeur Blizzard quand l'habillage est désactivé.")
