T("Center keeps the whole visible cooldown row centered as icons appear or disappear. Enable Keep first icon centered for alternating growth around the first icon. Buff icons then keep fixed places, with gaps for inactive buffs. Attach the bar to another bar or to your player frame; Gap controls the space between them.", "Centre garde toute la rangée visible de temps de recharge centrée lorsque des icônes apparaissent ou disparaissent. Activez Garder la première icône au centre pour ajouter les suivantes alternativement autour de la première. Les icônes d’améliorations gardent alors des places fixes, avec des espaces pour les améliorations inactives. Ancrez la barre à une autre barre ou au cadre du joueur ; Espacement règle la distance entre eux.")
