T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "Choisissez Moderne épuré, Midnight Blue, Verre MSUF Forever, Midnight Dark ou Style de classe pour l'habillage et les modules actifs de la Suite. Les modules activés plus tard en héritent.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Choisissez Moderne épuré, Midnight Blue, Midnight Dark, MSUF Forever ou Style de classe. Seules les couleurs et l'opacité de la fenêtre des sacs changent ; les emplacements et actions Blizzard sont conservés.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Choisissez Clean Modern, Midnight Blue, le verre neutre Midnight Dark ou le cadre doré sombre de MSUF Forever. Tous utilisent la texture de barre et la police MSUF. Activez ou désactivez les 20 segments d'EXP. La ligne inférieure peut afficher l'EXP gagnée pendant la session, l'EXP par heure et le temps restant avant le prochain niveau. Déplacez ou redimensionnez la barre dans le mode Édition MSUF ; sa fenêtre permet de régler X, Y, largeur, hauteur et échelle. Survolez la barre pour voir les valeurs exactes. La session survit à /reload et recommence à la connexion suivante.")
T("Choose Craft quantity to change how many times you plan to craft this tracked recipe.", "Choisissez Quantité à fabriquer pour modifier le nombre prévu pour cette recette suivie.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Choisissez Disposition personnalisée pour définir l'ordre des valeurs totales, par seconde et en pourcentage, puis choisissez des espaces, des crochets ou un séparateur. L'option de pourcentage contrôle les lignes principales ; les lignes de détail affichent les parts disponibles. Les parts indisponibles sont omises. Principale signifie par seconde pour DPS/HPS et total pour les autres compteurs. Les réglages de texte s'appliquent aussi aux en-têtes, aux détails et au chronomètre flottant. Slug utilise le rendu de police net de WoW, avec contour et sans ombre. Les valeurs protégées s'affichent sans pourcentage jusqu'à la fin du combat.")
