T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Choisissez une police MSUF, un contour, une ombre et un rendu Lisse, Net ou Slug. Slug n'a pas d'ombre. Les couleurs du libellé, de la valeur et d'avertissement sont séparées.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Choisissez une police et une texture de barre MSUF ou SharedMedia. La taille de police, le contour, l'ombre, le rendu Lisse/Net/Slug, la hauteur de barre et l'espacement mettent l'ATH à jour immédiatement. Slug n'a pas d'ombre.")
