T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Choisissez de grandes familles d'interface. Le comportement sécurisé dédié et les graphismes porteurs de sens restent intacts.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Choisissez les noms de broker et les identifiants des monnaies découvertes pour chaque emplacement. Sélectionnez vos monnaies d’écus de la saison actuelle dans la liste native ; les choix enregistrés fonctionnent après connexion sans rendre visite au PNJ d’amélioration. L’ordre de sélection et le séparateur contrôlent le bloc d’écus. Les paliers d’amélioration observés restent disponibles comme alternative après avoir sélectionné un objet à améliorer pendant cette session. Les actions de pierre de foyer nécessitent un clic volontaire.")
T("Choose buffs and consumables to track.", "Choisissez les améliorations et consommables à suivre.")
