T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Choisissez chaque popup Blizzard séparément. La fonctionnalité masque sa fenêtre lorsqu'elle apparaît et laisse intacts les événements de jeu sous-jacents. Le verrouillage de combat peut empêcher de cacher une fenêtre protégée.")
