T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Choisissez une police pour le texte de l'interface Blizzard. Les tailles, contours, ombres et la mise à l'échelle d'accessibilité existants sont conservés.")
