T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Choisissez la vue détaillée du personnage et ses informations supplémentaires. Changer de vue recharge l'interface.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Choisissez les difficultés de donjon où MSUF lance le journal de combat. En Mythique+, il démarre avec la clé.")
T("Choose the map shape, then adjust its border and outer shadow.", "Choisissez la forme de la carte, puis ajustez sa bordure et son ombre extérieure.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Choisissez les difficultés de raid où MSUF lance le journal de combat.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Choisissez les couleurs et le cadre communs des boutons. La disposition, les raccourcis et la visibilité restent tels quels. Modifier une couleur individuelle fait passer le libellé à Personnalisé.")
T("Choose the values shown on each bar.", "Choisissez les valeurs affichées sur chaque barre.")
T("Choose this character's class and specialization above.", "Choisissez ci-dessus la classe et la spécialisation de ce personnage.")
T("Choose this item to add it to your list.", "Choisissez cet objet pour l’ajouter à votre liste.")
T("Choose volumes for each activity. Turning this off restores the previous volumes when they are still owned by MSUF.", "Choisissez les volumes par activité. La désactivation restaure les valeurs précédentes encore gérées par MSUF.")
T("Choose what the Suite tracker lists and when it steps aside.", "Choisissez ce que le suivi Suite affiche et quand il s’efface.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Choisissez où apparaissent les actions récentes. Les gouffres ont leur propre interrupteur ; les champs de bataille et les arènes en partagent un, et les autres scénarios suivent « Hors des instances ». Là où le suivi est désactivé, il n'écoute pas vos sorts.")
T("Choose whether the Time place shows the realm clock or your computer's clock, in 12 or 24 hours, with or without seconds.", "Choisissez si l'emplacement Heure affiche l'heure du royaume ou celle de votre ordinateur, sur 12 ou 24 heures, avec ou sans secondes.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Choisissez quelles interfaces Blizzard reçoivent l'habillage. Blizzard conserve leurs interactions.")
T("Choose which learned portals the minimap flyout and the DataText portal and travel menus list: all of them, those of the current Mythic+ season, which the game keeps up to date each season, or your own set. Learned dungeon portals use secure buttons. Group suggestions require a verified dungeon map or an exact destination match and consider every learned portal. Unknown destinations show no suggestion; buttons hide in combat.", "Choisissez les portails appris qu’affichent le menu déroulant de la minicarte et les menus Portails et Voyages des textes de données : tous, ceux de la saison Mythique+ actuelle, que le jeu tient à jour à chaque saison, ou votre propre ensemble. Les portails de donjon appris utilisent des boutons sécurisés. Les suggestions de groupe nécessitent une carte de donjon vérifiée ou une destination identique et tiennent compte de tous les portails appris. Les destinations inconnues ne génèrent aucune suggestion ; les boutons sont masqués en combat.")
T("Choose your alt, subject and material quantities. Apply and attach from the Send Mail tab, then review and send manually.", "Choisissez votre personnage, l’objet et les quantités. Appliquez-les dans Envoyer du courrier, vérifiez et envoyez manuellement.")
T("Choose your buffs or your own harmful auras on the current target. The additional required buff is always checked on you.", "Choisissez vos améliorations ou vos propres auras néfastes sur la cible actuelle. L’amélioration supplémentaire requise est toujours vérifiée sur vous.")
T("Choose your character", "Choisissez votre personnage")
T("Choose your lure; other consumables are also listed.", "Choisissez votre appât ; les autres consommables sont aussi affichés.")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Choisir un thème met à jour l'habillage et chaque module actif de la Suite. Les modules activés plus tard en héritent. Les nouveaux profils d'habillage commencent avec %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "La confirmation peut être ignorée après votre choix de quitter la cinématique. Le passage automatique est une option distincte qui inclut aussi les vidéos. Les deux sont inactifs en combat, et une séquence en véhicule garde toujours sa confirmation de sortie. Cet assistant peut masquer les didacticiels, préremplir le mot de suppression en vous laissant la confirmation finale, masquer uniquement la confirmation de capture d'écran ou ouvrir votre fiche de personnage chez les marchands, sur le dernier onglet utilisé. À l'hôtel des ventes, le bouton de filtres de Blizzard est marqué tant que « Extension actuelle uniquement » est désactivé ; cochez-le là une fois et Blizzard le garde pour ce personnage.")
T("Cinematic zone and event announcements in the Suite look.", "Annonces cinématiques de zone et d'événement au style de la Suite.")
