T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "Moderne épuré est le défaut de Retail ; MSUF Forever est celui de Forever. Midnight Blue conserve le verre bleu d'origine. Ouvrez le menu à trois points d'une section pour changer ses couleurs, ou Couleurs MSUF pour toute la palette. Vos modifications deviennent Personnalisé.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "Moderne épuré utilise des panneaux mats avec des accents blancs. Midnight Blue conserve la palette bleue d'origine. Midnight Dark utilise un verre anthracite neutre ; MSUF Forever conserve son or discret. Les modifications de couleur deviennent Personnalisé.")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "Moderne épuré, Midnight Blue, Midnight Dark et MSUF Forever sont des thèmes complets dans Style. Ici, les palettes ne changent que les couleurs ; utilisez le mode Expert pour chaque état de l'interface.")
