T("Dark panel keeps the bank's usual color for the Suite bank views; Match the bag window follows the bag background color and look. The panel stays opaque so Blizzard's own slots never show through it. The size and position apply to the whole bank window, also in Bank tabs. Move the open bank in MSUF Edit Mode, or set the offsets here after turning on the custom position.", "Panneau sombre conserve la couleur habituelle de la banque dans les vues Suite ; Comme la fenêtre des sacs reprend leur couleur et leur style. Le panneau reste opaque pour masquer les emplacements Blizzard derrière lui. La taille et la position concernent toute la fenêtre, y compris les onglets de banque. Déplacez la banque ouverte en mode Édition MSUF ou activez la position personnalisée puis réglez les décalages ici.")
