T("Docked timers follow the selected window and hide with it. Positive horizontal offsets move right; positive vertical offsets move up.", "Les chronomètres ancrés suivent la fenêtre choisie et se masquent avec elle. Un décalage horizontal positif va à droite ; un décalage vertical positif va vers le haut.")
