T("Double", "Double")
T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Double-cliquez sur un résultat de recherche pour ouvrir la fenêtre de candidature de Blizzard. Avec l'envoi par double-clic, le second clic vous inscrit aussi avec les rôles déjà choisis dans cette fenêtre ; maintenez Maj pour la vérifier à la place. Une note enregistrée peut s'afficher à côté de la fenêtre pour être copiée ; elle est enregistrée lorsque vous terminez la saisie.")
T("Double-click a search result to open Blizzard's normal application dialog.", "Double-cliquez sur un résultat de recherche pour ouvrir la fenêtre normale de candidature de Blizzard.")
T("Draft saved", "Brouillon enregistré")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Faites glisser une fenêtre par son bord supérieur ; faites glisser le coin inférieur droit pour la redimensionner. Le bouton moins en haut à droite replie les fenêtres compatibles en un onglet de restauration. Les sacs et les fenêtres protégées gardent leur comportement natif.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Faites glisser les annonces dans le mode Édition MSUF, ou réglez ici leur durée, leur échelle et leur position exacte.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "Faites glisser ou utilisez les flèches pour déplacer ; Maj : 5, Ctrl : 10.")
T("Drag or use arrows to move; click for settings.", "Faites glisser ou utilisez les flèches pour déplacer ; cliquez pour les réglages.")
T("Drag the bag title to move it; click for options.", "Faites glisser le titre du sac pour le déplacer ; cliquez pour les options.")
T("Drag the bar's edge to move it on screen.", "Faites glisser le bord de la barre pour la déplacer à l'écran.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Faites glisser le titre du sac de composants quand il est ouvert pour le déplacer séparément. Cliquez sur le titre pour les options du sac. Réinitialisez sa position dans le mode Édition MSUF pour suivre à nouveau la disposition normale des sacs de Blizzard.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Déplacez la carte de résultat en mode Édition de MSUF ou réglez ici son ancrage, sa largeur, son échelle et sa position.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Faites glisser le titre d'un sac ouvert pour le déplacer. Cliquez sur le titre pour les options du sac. Chaque sac garde sa propre position. Blizzard affiche votre or actuel à droite ; la valeur facultative Session à gauche montre la variation depuis la connexion et survit à /reload. Ajustez ici la taille des sacs combinés ou dans sa fenêtre du mode Édition MSUF. Réinitialiser la position dans le mode Édition ramène la fenêtre à l'ancre normale de Blizzard.")
