T("Drop an item here to add it without moving it.", "Déposez un objet ici pour l'ajouter sans le déplacer.")
T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "Déposez un objet sur Objets épinglés dans la barre latérale pour le garder en haut de chaque vue. Objets récents liste jusqu'à 200 types d'objets reçus par ce personnage, aussi d'une connexion à l'autre ; chacun quitte la liste une fois plus ancien que les heures réglées ici, et Vider les objets récents la vide plus tôt. Aucune de ces actions ne déplace ni ne supprime d'objet.")
T("Dropdown and previous/next arrows", "Flèches des menus déroulants et précédent/suivant")
T("Drops this bar's own order and the spells and items you added to it, for this specialization. Spells you removed stay hidden: Show removed spells brings them back. You can undo it.", "Abandonne l'ordre propre de cette barre ainsi que les sorts et objets que vous y avez ajoutés, pour cette spécialisation. Les sorts retirés restent masqués : Afficher les sorts retirés les rétablit. Vous pouvez annuler.")
