T("Each response is its own switch and none acts in combat. A summon that skips a starting area, and a resurrection during a boss encounter or while Blizzard makes you wait, stay yours. Party invite declines never touch friends, Battle.net friends or guild members, and invites that ask for a role or start a quest session stay yours. A chat line can report each response.", "Chaque réponse possède son propre réglage et n'agit jamais en combat. Vous répondez aux invocations qui passent une zone de départ et aux résurrections pendant un boss ou une attente imposée par Blizzard. Les refus d’invitations de groupe ne concernent jamais les amis, amis Battle.net ou membres de la guilde. Les invitations demandant un rôle ou démarrant une session de quêtes restent manuelles. Chaque réponse peut être signalée dans la discussion.")
T("Each specialization keeps its own bar layout: positions, attachments, growth, rows, spacing and sizes. Until it has its own, it uses the current one.", "Chaque spécialisation garde sa propre disposition des barres : positions, ancrages, croissance, rangées, espacement et tailles. Tant qu'elle n'en a pas, elle utilise la disposition actuelle.")
T("Each window keeps its own meter, fight, size and visibility rules. Drag the header or use MSUF Edit Mode to move it.", "Chaque fenêtre garde son propre compteur, combat, taille et règles de visibilité. Faites glisser l'en-tête ou utilisez le mode Édition MSUF pour la déplacer.")
