T("Enter a spell name or ID on MSUF action bars. Its buttons glow from the aura and unit selected below. A page change in combat pauses the glow until combat ends.", "Saisissez le nom ou l’ID d’un sort des barres MSUF. Ses boutons brillent selon l’aura et l’unité choisies ci-dessous. Un changement de page en combat suspend la lueur jusqu’à la fin du combat.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Saisissez le nom ou l'identifiant d'un talent ou sort, puis appuyez sur Entrée. Tous les sorts requis doivent être appris. Un champ vide supprime cette condition.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Saisissez le nom ou l'identifiant d'un talent ou sort, puis appuyez sur Entrée. L'entrée est masquée si l'un des sorts exclus est appris. Les conditions sont actualisées hors combat.")
