T("Enter the cast spell's name or ID. Leave empty for automatic spell matching. Timers start only from readable player cast events.", "Saisissez le nom ou l’identifiant du sort lancé. Laissez vide pour une association automatique. Les minuteurs ne démarrent que sur les événements de lancement lisibles du joueur.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Saisissez jusqu'à 200 ID d'objet. Le bouton n'apparaît que chez un marchand et affiche les piles admissibles avant la confirmation. L'assistant revérifie l'identité, la qualité, la valeur, l'état de quête et la position dans le sac avant de demander la vente. L'inclusion des objets équipables nécessite une option distincte.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Saisissez jusqu'à huit ID de sorts de déplacement. Lorsque vous commencez à bouger, le premier sort connu, prêt et utilisable apparaît brièvement ; un temps de recharge commun de 20 secondes limite les alertes. Les champs vides ne font rien. Le mode Édition MSUF permet de déplacer l'alerte.")
