T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "Les choix d'équipement (la liste qui s'ouvre depuis un emplacement) affichent le niveau de chaque objet pour comparer sans survol. Les flèches à côté des emplacements peuvent être masquées ; maintenez Alt sur un emplacement pour ouvrir ses choix.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "Les niveaux d'objet de l'équipement apparaissent en haut à droite de chaque emplacement. Choisissez une police, un contour, une ombre et un rendu Lisse, Net ou Slug. Slug n'a pas d'ombre. Les données d'objet manquantes apparaissent dès que le client les fournit.")
