T("Font, text sizes and background opacity. The tracker colors are in this section's three-dot menu; picking one switches the color source to Custom colors.", "Police, tailles de texte et opacité du fond. Les couleurs du suivi se trouvent dans le menu à trois points de cette section ; en choisir une passe la source des couleurs en Couleurs personnalisées.")
T("Fonts", "Polices")
T("Fonts, outlines, shadows and Smooth/Sharp/Slug rendering for keybinds, macro names, counts and cooldown numbers. Sizes are set per bar below. Slug has no shadow.", "Polices, contours, ombres et rendu Lisse/Net/Slug pour les raccourcis, noms de macro, compteurs et chiffres de recharge. Les tailles se règlent par barre ci-dessous. Slug n'a pas d'ombre.")
