T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Pour les démonistes : affiche Ruée ardente uniquement lorsque son aura est active en combat. Le conteneur d'auras natif de Blizzard suit cette aura ; Suite ne parcourt pas les auras. Le mode Édition MSUF affiche un aperçu et permet de déplacer l'alerte.")
T("Forces", "Forces")
T("Forever Suite layout with Antique Map and optional parchment Skin.", "Disposition Suite Forever avec Antique Map et Skin parchemin facultatif.")
T("Forever artwork", "Illustrations Forever")
T("Forever factory profile unavailable", "Profil d'usine Forever indisponible")
T("Forever only. A secure fishing key that casts Fishing, equipping the rod you choose first, and a second key that applies the lure you choose. Set both under Keybindings > MSUF Suite. Each action needs your key press; interacting with the bobber stays manual. The optional sound profile sets your fishing volumes while you cast and restores them afterwards.", "Forever uniquement. Une touche de pêche sécurisée équipe d'abord la canne choisie puis lance Pêche ; une seconde applique l'appât choisi. Assignez les deux dans Raccourcis > MSUF Suite. Chaque action nécessite une pression ; l'interaction avec le bouchon reste manuelle. Le profil audio facultatif règle les volumes de pêche au lancer puis les rétablit.")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Forever uniquement. Les durées des trajets complets sont apprises et conservées dans ce profil. Aucun temps n’est inventé pour le premier trajet. Un atterrissage anticipé ne remplace pas la durée complète. Les escales viennent de la carte native et son infobulle peut prévisualiser le trajet. « Atterrir au prochain arrêt » demande le prochain point disponible.")
T("Forever only. When a quest offers a choice of rewards, the one with the highest vendor value, counting its stack size, is marked. Nothing is selected or turned in for you.", "Forever uniquement. Lorsqu'une quête offre plusieurs récompenses, celle dont le prix de vente total est le plus élevé, quantité comprise, est marquée. Rien n'est sélectionné ni rendu à votre place.")
