T("Frames join aligned bars; detached bars keep separate frames. Effects are static. Threshold marks a fixed percentage. Preview switches apply live.", "Le cadre extérieur réunit les barres de vie et de sort ; sans sort visible, il entoure uniquement la vie. L’ombre et la lueur sont fixes. Les textures conservent les couleurs de vie et d’auras. Le repère indique un pourcentage fixe et non une alerte d’exécution. Activez chaque fonction dans les calques de l’aperçu. Les barres séparées ou de tailles différentes gardent des cadres distincts.")
