T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "Affichage des joueurs alliés choisit le réglage Blizzard, les noms de tous les joueurs alliés, les noms du groupe / raid uniquement, ou les barres de vie. Noms uniquement masque les barres, incantations et auras Blizzard des joueurs alliés ; cela ne change pas les barres des PNJ ni des ennemis. Groupe / hors groupe dans l'aperçu ne change que l'exemple. Blizzard peut interdire les modifications des barres alliées en instance ; ces cadres restent sous le contrôle de Blizzard.")
