T("Gives Blizzard's player buffs and debuffs the icon skins you chose on the Icon Skins page, at Blizzard's own size and layout. The skins are painted once, out of combat, and no code runs on aura updates. While Player aura layout is on, it paints the buttons itself and this switch waits.", "Applique aux améliorations et affaiblissements du joueur de Blizzard les habillages choisis sur la page Habillages d'icônes, en conservant la taille et la disposition natives. L'habillage est appliqué une fois, hors combat, sans code lors des mises à jour d'auras. Si Disposition des auras du joueur est activé, cette fonction dessine les boutons et ce réglage attend.")
T("Gives this bar's place, attachment, growth, rows and sizes to your other specializations. You can undo it.", "Applique la position, l’ancrage, le sens de croissance, les rangées et les tailles de cette barre aux autres spécialisations. Vous pouvez annuler.")
