T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Maintenez Alt pour voir l'ID d'un objet, sort, d'une créature, quête, monnaie ou d'un enchantement temporaire d'arme dans son infobulle, ou appuyez sur Alt infobulle ouverte ; les ID restent jusqu'à ce que l'infobulle soit reconstruite. Les ID d'icônes de sort et les données de monnaie de vos autres personnages fournies par Blizzard sont facultatives, et ces données rejoignent une infobulle ouverte à leur arrivée. Aucun ID ni aucune quantité n'apparaît quand le client les garde privés.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "Maintenez Alt pour afficher dans l'infobulle principale les ID des objets, sorts, créatures, quêtes, monnaies et enchantements d'arme temporaires.")
