T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "Maintenez la touche choisie en cliquant sur Libérer l'esprit. Le bouton reste masqué tant que vous ne la maintenez pas ; la résurrection et le récapitulatif de mort restent disponibles. Choisissez où activer cette protection. Le compte à rebours de libération automatique de Blizzard reste inchangé.")
