T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "En raid, le suivi devient une vue de rencontre à sa place habituelle : nom du boss, chrono du pull, boss engagés avec leur vie, votre meilleur wipe et votre kill le plus rapide. Les phases viennent de DBM ou BigWigs si l’un d’eux est installé ; sinon la phase reste inconnue. Un wipe avec plus de boss vaincus bat un wipe avec moins, et à nombre égal celui qui laisse le moins de vie aux boss l’emporte. Chaque personnage garde ses propres records. La vie des boss ne s’affiche que lorsque le client la révèle.")
