T("Item tooltips take the color of the item quality, unit tooltips the class color of a player or the reaction color of any other unit. Keep leaves the border as it is. The Suite skin's tooltip border takes the color too.", "Les infobulles d'objets prennent la couleur de leur qualité ; celles des unités, la couleur de classe des joueurs ou de réaction des autres unités. Conserver laisse la bordure inchangée. La bordure de l'habillage Suite prend aussi cette couleur.")
