T("Items you protect are skipped by every sale action of the Suite. With the equipment set switch on, all equippable items are protected while any equipment set exists, because exact set membership is not available to this helper. Manage the protected items in the inventory tool.", "Les objets protégés sont exclus de toutes les ventes de la Suite. Si la protection des ensembles d'équipement est activée, tous les objets équipables sont protégés dès qu'un ensemble existe, car cet outil ne peut pas déterminer leur appartenance exacte. Gérez les objets protégés dans l'outil d'inventaire.")
