T("Keep", "Conserver")
T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Sort items by orders every Suite view; Name keeps the order each view has always had. Click a category header to hide or show its items. The footer counts free slots, and Mark items that beat what you wear puts a small arrow on equipment that beats what you wear in its slot. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Conservez la grille Blizzard ou choisissez une grille Suite, des groupes de sacs physiques ou des catégories. Modifier les catégories dans la fenêtre des sacs permet de les créer, renommer, réordonner ou désactiver ; déposez des objets sur une catégorie latérale pour les y affecter. Trier les objets par ordonne chaque vue Suite ; Nom conserve l'ordre habituel. Cliquez sur un en-tête de catégorie pour masquer ou afficher ses objets. Le pied de page compte les emplacements libres ; Marquer les objets meilleurs que votre équipement ajoute une flèche aux améliorations pour l'emplacement concerné. Faites défiler ou utilisez Précédent et Suivant pour les grands inventaires ; en combat, tous les emplacements s'affichent à la fois. Les quantités de piles combinées sont uniquement visuelles ; les piles physiques sont toujours rétablies à la banque, banque de guilde, poste, échange, hôtel des ventes et marchand.")
