T("Lightweight meter windows for damage, healing, interrupts, dispels, deaths and damage taken. They read the client's own combat data; Blizzard's meter window stays hidden while this module is active.", "Fenêtres de compteur légères pour les dégâts, soins, interruptions, dissipations, morts et dégâts subis. Elles lisent les données de combat du client ; la fenêtre du compteur de Blizzard reste masquée tant que ce module est actif.")
