T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "Affiche les types de gemmes transportées à côté de la fenêtre de sertissage de Blizzard. Examinez chaque gemme avec l'infobulle normale du sac et vérifiez sa compatibilité dans la fenêtre native avant de l'appliquer.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "Liste les incantations des ennemis attaquables dotés d'une barre d'info dans un donjon à cinq joueurs, de la plus ancienne à la plus récente ; le jeu gère chaque barre et chaque minuteur. Le jeu cache aux addons le sort, la cible, le marqueur et la possibilité d'interrompre, donc les incantations ne sont jamais triées ni filtrées selon ces critères : estomper ou masquer utilise le marquage de sort important du jeu (une incantation masquée garde sa place dans la liste), les marqueurs de raid se placent sur l'icône du sort et la marque « prête », une bande au bord ou toute la barre, apparaît sur les incantations interruptibles tant que votre interruption n'est pas en recharge. L'assombrissement vérifie quatre fois par seconde si votre interruption atteint chaque ennemi listé ; une incantation impossible à vérifier reste claire. L'interruption est déterminée par vos talents et votre familier, sauf si vous saisissez un ID de sort. Le mode Édition de MSUF affiche des incantations d'exemple pour placer la liste.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "Liste les incantations des barres d'info ennemies dans les donjons à cinq joueurs, de la plus ancienne à la plus récente, avec des minuteurs gérés par le jeu.")
