T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF n'arrête qu'un journal qu'il a lancé. Un journal déjà actif le reste. Revenir dans le contenu choisi annule un arrêt en attente. WoW écrit le journal dans son dossier Logs.")
