T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline couvre les poisons de voleur, les flacons, runes d'amélioration et huiles d'arme de cette saison, ainsi que l'amélioration de nourriture Bien nourri. Chaque catégorie utilise au clic le premier objet correspondant de vos sacs ; un objet que vous indiquez pour elle est essayé en premier. La nourriture est trouvée dans vos sacs grâce aux sorts de repas du jeu : d'abord celle que vous indiquez, puis la plus récente. Avec le rappel gris, une catégorie épuisée reste visible sans action au clic. Assassinat préfère le Poison mortel ; Hors-la-loi et Finesse préfèrent le Poison instantané. Lames trempées par les dragons permet deux poisons par catégorie. Les huiles visent les armes équipées ; les enchantements connus de chaman ou de paladin suppriment les huiles automatiques.")
