T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko utilise des plaques modernes, une taille moyenne et les mêmes dimensions sur Retail et Forever. Les noms de guilde et titres affectent aussi les noms dans le monde. Attribuez Basculer les plaques des PNJ amicaux sous MSUF Suite dans les raccourcis Blizzard. La protection d'import conserve vos plaques lors d'un import complet de Suite ; les imports explicites de plaques les remplacent toujours.")
