T("Pick the places where reminders may show; arenas and battlegrounds never show them. Before a keystone starts, buffs can be asked to last the dungeon's timer or a number of minutes; once the key starts, the normal warning time applies again. One scheduled wakeup handles the next expiry.", "Choisissez les lieux où les rappels peuvent apparaître ; ils n'apparaissent jamais en arène ni en champ de bataille. Avant le début d'une clé, on peut exiger que les améliorations durent le chronomètre du donjon ou un nombre de minutes ; une fois la clé lancée, le délai d'alerte normal revient. Un seul réveil planifié gère la prochaine expiration.")
