T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "Priorité : focalisation, aggro sûre du tank, menace, engagé, quête, neutre, puis type de PNJ. Désactiver la focalisation autorise la règle suivante. Les remplacements de menace désactivés conservent la couleur de menace active de Blizzard. Le mode tank utilise votre rôle effectif ; les alertes fonctionnent aussi pour les DPS et soigneurs. Les valeurs secrètes restent gérées par Blizzard.")
