T("Remembers your characters that you visit while this helper is on and lists them beside the mail window. Click a name to fill the recipient, right-click to hide or restore it, and search by name. Only characters on your current or connected realms are listed. Sending stays manual.", "Mémorise les personnages avec lesquels vous vous connectez lorsque cet outil est activé et les affiche près de la fenêtre de courrier. Cliquez sur un nom pour remplir le destinataire, faites un clic droit pour le masquer ou le rétablir et recherchez par nom. Seuls les personnages du royaume actuel ou des royaumes connectés sont affichés. L'envoi reste manuel.")
