T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "Les rappels n'apparaissent que hors combat. Le réglage d'anticipation affiche aussi les buffs actifs, la nourriture et les enchantements d'arme quand leur temps restant atteint le nombre de minutes choisi ; 0 n'affiche que les effets manquants. Un seul réveil programmé gère le seuil suivant. Les rappels sont masqués en arène et en champ de bataille, où les données d'aura peuvent être restreintes.")
T("Reminders for missing poisons and consumables.", "Rappels des poisons et consommables manquants.")
T("Reminders for the buffs your class and specialization keep up.", "Rappels des améliorations à maintenir pour votre classe et spécialisation.")
