T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "Répare l'équipement et vend les objets de qualité médiocre à l'ouverture d'un marchand. Maintenez Maj pour ne pas vendre.")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "Répare uniquement si le coût reste dans votre limite. Les fonds de guilde sont utilisés en premier si c'est autorisé.")
