T("Signal", "Signal")
T("Silences the game sound files whose IDs you list, such as a mount or summon sound; up to 200. MSUF mutes exactly the files listed here and plays them again when you remove an ID or turn this helper off, and it leaves files muted by other addons alone. Muting works whether or not volume profiles are applied.", "Coupe les fichiers audio du jeu dont vous indiquez les ID, par exemple les sons de montures ou d'invocations ; jusqu'à 200. MSUF ne coupe que ces fichiers et les rétablit lorsque vous retirez un ID ou désactivez l'outil. Les fichiers coupés par d'autres addons restent inchangés. Cela fonctionne avec ou sans profils de volume.")
T("Silences these game sound files, such as a mount or summon sound, while this helper is on. Remove an ID to hear that sound again.", "Coupe ces fichiers audio du jeu, comme les sons de montures ou d'invocations, tant que l'outil est activé. Retirez un ID pour entendre à nouveau le son.")
