T("Size and look of aura timer bars and cooldowns displayed as timer bars. Stack-filled buff bars use the native stack binding; stack glows remain available on icon and duration views.", "Taille et apparence des barres de temps d'auras et des temps de recharge affichés en barres. Les barres d'améliorations remplies selon les charges utilisent la liaison native des charges ; les lueurs de charges restent disponibles pour les icônes et les vues de durée.")
