T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. The bank views have the same smart search, free slot count and collapsible category headers. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Le bouton sous la banque permet de passer des onglets natifs à la banque combinée, à la banque de bataillon combinée ou aux catégories communes. Celles-ci incluent les onglets accessibles du personnage et du bataillon. Gérer les onglets de banque revient aux achats, dépôts et réglages Blizzard. Les vues proposent la même recherche intelligente, le nombre d'emplacements libres et les en-têtes repliables. Chaque emplacement conserve son action et les piles de banque ne sont jamais fusionnées ; cliquer sur un objet de bataillon sélectionne d'abord l'onglet Banque de bataillon de Blizzard. Un objet remboursable demande confirmation avant d'y être déposé.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "Activez ou désactivez chaque barre ici. La réactivation restaure son mode de visibilité précédent. Choisissez Disposition pour personnaliser la barre sélectionnée en haut.")
T("Switch on the first option, then keep or drop the reminders you want. A reminder shows only when your character knows its spell. Stances, auras, shields, Shadowform and weapon or shield imbues show while they are missing. Buffs you put on an ally (Source of Magic, Blistering Scales, Earth Shield, Symbiotic Relationship) show while your buff is on nobody in the group; target an ally and click the icon to cast it. Right-click or middle-click any reminder to hide it until you reload the UI.", "Activez la première option, puis gardez ou désactivez les rappels souhaités. Un rappel apparaît uniquement si votre personnage connaît le sort. Postures, auras, boucliers, Forme d’ombre et améliorations d’arme ou de bouclier apparaissent lorsqu’ils manquent. Les améliorations placées sur un allié (Source de magie, Écailles torrides, Bouclier de terre, Relation symbiotique) apparaissent lorsque personne du groupe ne bénéficie de votre sort ; ciblez un allié et cliquez sur l’icône pour le lancer. Un clic droit ou central sur un rappel le masque jusqu’au rechargement de l’interface.")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "Activez ici l'ensemble du module d'habillage, ou réglez séparément les fenêtres Blizzard et de la Suite ci-dessous.")
