T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "Cochez chaque démon que vous voulez avoir ; vous pouvez aussi cocher des démons que votre personnage n'a pas encore appris. Un démon invoqué non coché reçoit un avis, tant que l'un de vos démons cochés peut être invoqué. Une autre apparence d'un démon compte comme ce démon dès que vous l'avez invoqué sous cette apparence.")
