T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "L'horodatage utilise le réglage de discussion de Blizzard dans toutes les fenêtres de discussion. Copier est désactivé par défaut ; une fois activé, déplacez son bouton avec X/Y, choisissez un message, puis appuyez sur Ctrl+C. L'horodatage affiché est inclus quand l'horodatage est actif. Les outils de messages ne touchent pas au journal de combat (ses propres réglages peuvent horodater chaque ligne) ; ses lignes réveillent quand même le fondu d'inactivité. L'historique enregistré appartient à ce personnage.")
