T("Type", "Type")
T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "Tapez /keys ou /msufkeys pour voir votre clé mythique actuelle. Ajoutez party, raid ou instance pour la partager sur ce canal. /keys group demande les clés des membres du groupe qui utilisent cet assistant Suite. L'alias /keys n'est utilisé que si aucun autre addon ne l'a enregistré. Dans les donjons et les raids, Blizzard bloque la discussion pour les addons ; votre clé n'est alors affichée que pour vous.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. The guild chat in the Guild & Communities window can be covered as well; other communities stay visible. Reveal the chat again with the click chosen here. Messages keep arriving underneath.", "Tapez /msufguildprivacy ou utilisez le petit bouton ON/OFF au-dessus de la fenêtre principale de discussion. Toute fenêtre contenant le canal Guilde ou Officiers est entièrement masquée, même si elle regroupe d'autres canaux. La discussion de guilde de la fenêtre Guilde et communautés peut aussi être masquée ; les autres communautés restent visibles. Le clic choisi ici affiche de nouveau la discussion. Les messages continuent d'arriver derrière.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "Tapez /msufraid pour déployer le gestionnaire de raid de Blizzard, /msufpull [1-60] pour son compte à rebours natif, ou /msufmark tank ou /msufmark healer pour marquer un seul membre du groupe sans ambiguïté. Les marqueurs automatiques facultatifs ne fonctionnent que pour un tank ou soigneur clairement identifié dans un groupe de cinq, si vous êtes chef ou assistant. Les marqueurs existants ou occupés sont respectés. Les comptes à rebours, marqueurs et appels « Prêt ? » attendent tant que Blizzard les restreint en combat, en rencontre et en clé mythique ; les marqueurs automatiques réessaient ensuite.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "Tapez /way x y pour la carte actuelle ou /way mapID x y. /msufway fonctionne toujours. L'alias court /way est utilisé uniquement lorsqu'aucun autre module complémentaire ne le possède.")
