T("When BigWigs, Details or another addon provides LibKeystone or LibOpenRaid, a keys request asks it too, so players without the Suite are listed.", "Si BigWigs, Details ou un autre addon fournit LibKeystone ou LibOpenRaid, une demande de clés l'interroge aussi afin d'inclure les joueurs sans la Suite.")
T("When a dungeon queue pops", "Quand une file d'attente de donjon apparaît")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Quand un appel commence hors combat et que votre mana de soigneur est bas, une courte note indique combien il vous en reste ; elle devient rouge sous la moitié de votre limite. Seul votre propre mana est lu.")
T("When equipment sets exist, all equippable items are protected. Exact set membership is unavailable to this helper.", "Si des ensembles existent, tous les objets équipables sont protégés. Cet outil ne peut pas déterminer leur appartenance exacte.")
T("When leaving", "En partant")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Quand quelqu'un vous propose une résurrection, son dialogue reçoit un cadre vert, éventuellement avec le son de l'appel de Blizzard, et son bouton Accepter peut recevoir son propre cadre vert. Accepter reste votre clic.")
T("When the key ends", "À la fin de la clé")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Lorsque la fenêtre de recherche de groupe se ferme avec des candidatures encore actives, leur nombre est affiché dans votre discussion locale. Vos candidatures restent actives et aucun message n'est envoyé au groupe.")
T("When the selected bar appears", "Quand la barre choisie apparaît")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Quand cette barre s'affiche, et à quel point elle s'estompe hors combat. Les infobulles montrent un sort quand vous survolez son icône. Cette page et le mode Édition MSUF affichent toujours toutes les barres.")
T("When to remind", "Quand rappeler")
T("When to show", "Quand afficher")
T("Where", "Où")
T("Where are the Suite minimap settings?", "Où sont les réglages de la minicarte de Suite ?")
T("Where are the nameplate settings?", "Où sont les réglages des barres de nom ?")
T("Where is the cooldown manager?", "Où est le gestionnaire des temps de recharge ?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "Où chercher le buff ou le débuff. Automatique : sorts nocifs sur votre cible, tous les autres sur vous.")
T("Where to show recent actions", "Où afficher les actions récentes")
T("Which Blizzard auras each kind of plate shows.", "Quelles auras Blizzard chaque type de barre affiche.")
T("Which number is drawn on top when both show.", "Quel nombre est dessiné au-dessus quand les deux s'affichent.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Quels nombres s'affichent, lequel est dessiné au-dessus, ainsi que leur taille et leur place. Chaque sort peut différer : cliquez dessus dans l'aperçu. Les réglages de police ci-dessous s'appliquent à toutes les barres ; Slug n'a pas d'ombre.")
T("Which units get nameplates and how plates share space.", "Quelles unités ont une barre d'info et comment les barres partagent l'espace.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Lorsque les textes de données et cette option sont actifs, MSUF mémorise l'or de ce personnage à la connexion et après chaque changement d'argent. Survolez un texte Or ou Or de session pour voir le dernier total connu du compte et jusqu'à huit autres personnages. Aucun balayage en arrière-plan n'est effectué.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Tant que les textes de données sont actifs, masque le sac à dos et les emplacements de sacs de Blizzard. Un texte de données Place dans les sacs ouvre les sacs natifs au clic. Désactivez ceci pour rétablir les boutons Blizzard.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Pendant une clé, chaque boss vaincu indique votre avance ou votre retard : par rapport à votre meilleur temps sur ce boss, ou aux temps des boss de votre parcours terminé le plus rapide, à ce niveau de clé ou à n’importe lequel. Seuls les parcours terminés par ce personnage comptent. Avec les temps cibles activés, les boss encore en vie affichent le temps à battre.")
T("While the buff of this item's use lasts, the icon shows its duration and stacks instead of the cooldown.", "Pendant l’amélioration liée à l’utilisation de cet objet, l’icône affiche sa durée et ses charges au lieu du temps de recharge.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Tant que le buff de ce sort dure, l'icône affiche sa durée et ses cumuls au lieu du temps de recharge.")
T("While this is on, move the window in MSUF Edit Mode or with the two positions below. While it is off, Blizzard's Edit Mode places it.", "Lorsque ce réglage est activé, déplacez la fenêtre en mode Édition MSUF ou avec les deux positions ci-dessous. Sinon, le mode Édition de Blizzard la place.")
T("While you hold the key, a tooltip that the rules above would hide is shown.", "Tant que vous maintenez la touche, une infobulle normalement masquée par les règles ci-dessus s'affiche.")
