T("With every selected DoT active, even a lone one, the all-DoTs color wins over individual and role colors. Otherwise individual colors follow list order.", "Quand tous les DoTs sélectionnés sont actifs, même un seul, la couleur de tous les DoTs a priorité sur les couleurs individuelles et de rôle. Sinon, les couleurs individuelles suivent l’ordre de la liste.")
T("Withdraw", "Retirer")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "WoW Forever uniquement. Liste la menace de votre groupe sur l'ennemi surveillé d'après les données de menace de Blizzard, de la plus haute à la plus basse ; pour une cible amicale, son ennemi est utilisé. Les valeurs que le jeu masque sont omises. Tournez la molette sur la fenêtre quand plus de membres sont listés que de lignes affichées. La marque rouge indique où vous prendriez l'aggro, ce qui n'est pas le point où vous égalez le tank. Le compteur se redessine au plus cinq fois par seconde et ne lit aucun journal de combat.")
